void* WindowKeyedState(Window* win, uint32_t key, void* fresh, DropFn drop) {
    if (!win || !fresh || !drop) {
        if (fresh && drop) {
            drop(fresh);
        }
        return nullptr;
    }
    for (int i = 0; i < win->keyed.len; i++) {
        if (win->keyed[i].key == key) {
            drop(fresh);
            return win->keyed[i].ptr;
        }
    }
    KeyedSlot s = {};
    s.key = key;
    s.ptr = fresh;
    s.drop = drop;
    if (!VecAppend(win->keyed, s)) {
        drop(fresh);
        return nullptr;
    }
    return fresh;
}

void* WindowFrameKeyedState(Window* win, uint32_t key, void* fresh,
                            DropFn drop) {
    void* p = WindowKeyedState(win, key, fresh, drop);
    if (!p) {
        return nullptr;
    }
    for (int i = win->keyed.len - 1; i >= 0; i--) {
        if (win->keyed[i].key == key) {
            win->keyed[i].frameScoped = true;
            win->keyed[i].frame = win->frameSeq;
            break;
        }
    }
    return p;
}

LaidOutHeight* UseLaidOutHeight(Ctx* cx, Str name, float fallback) {
    static const uint32_t kKind = HashClickId(StrL("laid-out-height"));
    LaidOutHeight* slot = cx && cx->win
                              ? FrameKeyedState<LaidOutHeight>(
                                    cx, KeyedKey(KeyedName(cx, name), kKind))
                              : nullptr;
    if (!slot) {
        return nullptr;
    }
    slot->built = slot->measured >= 0 ? slot->measured : fallback;
    slot->inset = 0;
    slot->contentBox = false;
    return slot;
}

bool LaidOutHeightObserve(LaidOutHeight* slot, float boxHeight) {
    if (!slot) {
        return false;
    }
    float h = boxHeight - slot->inset;
    if (h < 0) {
        h = 0;
    }
    slot->measured = h;

    if (fabsf(h - slot->built) <= 0.5f) {
        slot->chase = 0;
        return false;
    }

    if (slot->chase >= 1) {
        return false;
    }
    slot->chase++;
    return true;
}

static void LaidOutHeightPrePaint(PaintCtx* ctx, El* e, void* user) {
    auto* slot = (LaidOutHeight*)user;
    float boxH = e->h;
    if (slot && slot->contentBox) {
        float bt = e->style.border > e->style.borderT ? e->style.border
                                                      : e->style.borderT;
        float bb = e->style.border > e->style.borderB ? e->style.border
                                                      : e->style.borderB;
        boxH -= e->style.pad.top + e->style.pad.bottom + bt + bb;
    }

    if (slot && slot->rebuild && !LayoutInScratchPass()) {
        float h = boxH - slot->inset;
        if (h < 0) {
            h = 0;
        }
        slot->measured = h;
        if (fabsf(h - slot->built) > 0.5f) {
            slot->built = h;
            slot->chase = 0;
            Ctx cx = slot->cx;
            if (slot->rebuild(slot->rebuildUser, &cx, e, h)) {
                IdsCollectChildren(e);
                LayoutEl(ctx, e, e->x, e->y, e->w, e->h, e->laidFont,
                         e->style.color);
            }
        }
        return;
    }
    if (LaidOutHeightObserve(slot, boxH) && ctx && ctx->window) {
        WindowRequestAnimationFrame(ctx->window);
    }
}

bool TrackLaidOutHeight(Ctx* cx, El* e, LaidOutHeight* slot) {
    return TrackLaidOutHeight(cx, e, slot, nullptr, nullptr);
}

bool TrackLaidOutHeight(Ctx* cx, El* e, LaidOutHeight* slot,
                        bool (*rebuild)(void* user, Ctx* cx, El* box,
                                        float height),
                        void* user) {
    if (!e || !slot || e->prePaint || e->customPaint) {
        return false;
    }
    slot->rebuild = rebuild;
    slot->rebuildUser = user;
    slot->cx = cx ? *cx : Ctx{};
    e->prePaint = &LaidOutHeightPrePaint;
    e->customUser = slot;
    return true;
}

void WindowKeyedSweep(Window* win) {
    if (!win) {
        return;
    }
    int keep = 0;
    for (int i = 0; i < win->keyed.len; i++) {
        KeyedSlot slot = win->keyed[i];
        if (!slot.frameScoped || slot.frame == win->frameSeq) {
            win->keyed[keep++] = slot;
            continue;
        }

        if (slot.ptr && slot.drop) {
            slot.drop(slot.ptr);
        }
    }
    win->keyed.len = keep;
}

EntityId WindowKeyedEntity(Window* win, App* app, uint32_t key, void* fresh,
                           DropFn drop) {
    if (!win || !app) {
        if (fresh && drop) {
            drop(fresh);
        }
        return {};
    }
    for (int i = 0; i < win->keyed.len; i++) {
        if (win->keyed[i].key != key) {
            continue;
        }

        if (EntityGet(app, win->keyed[i].entity)) {
            if (fresh && drop) {
                drop(fresh);
            }
            return win->keyed[i].entity;
        }
        win->keyed[i].entity = EntityNewRaw(app, fresh, nullptr, drop);
        return win->keyed[i].entity;
    }
    KeyedSlot s = {};
    s.key = key;
    s.entity = EntityNewRaw(app, fresh, nullptr, drop);
    VecAppend(win->keyed, s);
    return s.entity;
}

void* WindowMotionState(Window* win, uint32_t key, int size) {
    if (!win || size <= 0) {
        return nullptr;
    }
    for (int i = 0; i < win->motionSlots.len; i++) {
        if (win->motionSlots[i].key == key) {
            win->motionSlots[i].frame = win->frameSeq;
            return win->motionSlots[i].ptr;
        }
    }
    MotionSlotRec s = {};
    s.key = key;
    s.frame = win->frameSeq;
    s.ptr = AllocZero(1, size);
    VecAppend(win->motionSlots, s);
    return s.ptr;
}

uint32_t* WindowPlotAppearScopeToken(Window* win, uint32_t key) {
    return (uint32_t*)WindowMotionState(win, key, (int)sizeof(uint32_t));
}

uint32_t WindowPlotAppearScope(const Window* win) {
    if (!win || win->plotAppearScopes.len == 0) {
        return 0;
    }
    return win->plotAppearScopes[win->plotAppearScopes.len - 1];
}

void WindowMotionSweep(Window* win) {
    if (!win) {
        return;
    }
    int keep = 0;
    for (int i = 0; i < win->motionSlots.len; i++) {
        if (win->motionSlots[i].frame == win->frameSeq) {
            win->motionSlots[keep++] = win->motionSlots[i];
            continue;
        }
        Free(nullptr, win->motionSlots[i].ptr);
    }
    win->motionSlots.len = keep;
}

void WindowMotionFree(Window* win) {
    if (!win) {
        return;
    }
    for (int i = 0; i < win->motionSlots.len; i++) {
        Free(nullptr, win->motionSlots[i].ptr);
    }
    VecReset(win->motionSlots);
}

void WindowKeyedFree(Window* win) {
    if (!win) {
        return;
    }
    for (int i = 0; i < win->keyed.len; i++) {
        if (win->keyed[i].ptr) {
            if (win->keyed[i].drop) {
                win->keyed[i].drop(win->keyed[i].ptr);
            } else {

                Free(nullptr, win->keyed[i].ptr);
            }
        }
    }
    VecReset(win->keyed);
}

static void SubRemoveAt(App* app, int ix) {
    for (int k = ix; k + 1 < app->subs.len; k++) {
        app->subs[k] = app->subs[k + 1];
    }
    app->subs.len--;
}

static void ObserverRemoveAt(App* app, int ix) {
    for (int k = ix; k + 1 < app->observers.len; k++) {
        app->observers[k] = app->observers[k + 1];
    }
    app->observers.len--;
}

Subscription EntityObserveRaw(App* app, EntityId observed, Listener handler) {
    Subscription sub;
    if (!app || !observed.IsValid() || !handler.IsValid()) {
        return sub;
    }
    EntitySub s;
    s.id = app->nextSubId++;
    s.emitter = observed;
    s.handler = handler;
    VecAppend(app->observers, s);
    sub.id = s.id;
    return sub;
}

void EntityUnobserve(App* app, Subscription sub) {
    if (!app || !sub.IsValid()) {
        return;
    }
    for (int i = 0; i < app->observers.len; i++) {
        if (app->observers[i].id == sub.id) {
            ObserverRemoveAt(app, i);
            return;
        }
    }
}

int EntityObserverCount(App* app, EntityId observed) {
    if (!app) {
        return 0;
    }
    int n = 0;
    for (int i = app->observers.len - 1; i >= 0; i--) {
        if (!EntityGet(app, app->observers[i].handler.view)) {
            ObserverRemoveAt(app, i);
            continue;
        }
        if (app->observers[i].emitter == observed) {
            n++;
        }
    }
    return n;
}

Subscription EntitySubscribeRaw(App* app, EntityId emitter,
                                const void* eventType, Listener handler) {
    Subscription sub;
    if (!app || !emitter.IsValid() || !eventType || !handler.IsValid()) {
        return sub;
    }
    EntitySub s;
    s.id = app->nextSubId++;
    s.emitter = emitter;
    s.eventType = eventType;
    s.handler = handler;
    VecAppend(app->subs, s);
    sub.id = s.id;
    return sub;
}

void EntityUnsubscribe(App* app, Subscription sub) {
    if (!app || !sub.IsValid()) {
        return;
    }
    for (int i = 0; i < app->subs.len; i++) {
        if (app->subs[i].id == sub.id) {
            SubRemoveAt(app, i);
            return;
        }
    }
}

static void SweepSubs(App* app) {
    for (int i = app->subs.len - 1; i >= 0; i--) {
        const EntitySub& s = app->subs[i];
        if (!EntityGet(app, s.emitter) || !EntityGet(app, s.handler.view)) {
            SubRemoveAt(app, i);
        }
    }
}

void EntityEmitRaw(App* app, Window* win, EntityId emitter,
                   const void* eventType, const void* ev) {
    if (!app || !emitter.IsValid() || !eventType) {
        return;
    }
    SweepSubs(app);

    int n = app->subs.len;
    if (n <= 0) {
        return;
    }
    Subscription ids[64];
    int nIds = 0;
    for (int i = 0; i < n && nIds < 64; i++) {
        if (app->subs[i].emitter == emitter &&
            app->subs[i].eventType == eventType) {
            ids[nIds++].id = app->subs[i].id;
        }
    }
    for (int k = 0; k < nIds; k++) {
        for (int i = 0; i < app->subs.len; i++) {
            if (app->subs[i].id != ids[k].id) {
                continue;
            }
            Listener l = app->subs[i].handler;
            ListenerCall(app, win, l, ev);
            break;
        }
    }
}

int EntitySubscriberCount(App* app, EntityId emitter) {
    if (!app || !emitter.IsValid()) {
        return 0;
    }
    SweepSubs(app);
    int n = 0;
    for (int i = 0; i < app->subs.len; i++) {
        if (app->subs[i].emitter == emitter) {
            n++;
        }
    }
    return n;
}

