int Utf8OffsetToUtf16(Str s, int u8) {
    if (u8 > len(s)) {
        u8 = len(s);
    }
    int u16 = 0;
    int i = 0;
    while (i < u8) {
        unsigned char c = (unsigned char)s.s[i];
        int len = c < 0x80 ? 1 : (c < 0xE0 ? 2 : (c < 0xF0 ? 3 : 4));

        u16 += len == 4 ? 2 : 1;
        i += len;
    }
    return u16;
}

int Utf16OffsetToUtf8(Str s, int u16) {
    int at = 0;
    int i = 0;
    while (i < len(s) && at < u16) {
        unsigned char c = (unsigned char)s.s[i];
        int len = c < 0x80 ? 1 : (c < 0xE0 ? 2 : (c < 0xF0 ? 3 : 4));
        at += len == 4 ? 2 : 1;
        i += len;
    }
    return i;
}

