int WindowTimerMs(Window* win) {
    if (!win) {
        return 0;
    }

    double now = TimeNow();
    double soonest = -1;
    if (win->anim || win->opts.anim || win->animFrame) {

        double target = (win->lastDrawTime > 0)
                            ? (win->lastDrawTime + kAnimationFrameInterval)
                            : now;
        if (target < now) {
            target = now;
        }
        if (soonest < 0 || target < soonest) {
            soonest = target;
        }
    }

    for (int i = 0; i < win->timers.len; i++) {
        double due = win->timers[i].dueAt;
        if (due > 0 && (soonest < 0 || due < soonest)) {
            soonest = due;
        }
    }
    if (win->scrollDragNotifyPending && win->scrollDragNotifyDue > 0 &&
        (soonest < 0 || win->scrollDragNotifyDue < soonest)) {
        soonest = win->scrollDragNotifyDue;
    }
    if (win->touchHost == TouchHostKind::Pending) {
        double due = win->touchHostStartAt + kTouchLongPressS;
        if (soonest < 0 || due < soonest) {
            soonest = due;
        }
    }
    if (soonest < 0) {
        return 0;
    }
    int ms = (int)lround((soonest - now) * 1000.0);
    return ms > 0 ? ms : 1;
}

