static bool gGeomAsked = false;
static int gGeom[4] = {0, 0, 0, 0};

static bool ParseGeom(Str value, int out[4]) {
    int at = 0;
    for (int i = 0; i < 4; i++) {
        if (i > 0) {
            if (at >= len(value) || value.s[at] != ',') {
                return false;
            }
            at++;
        }
        bool neg = false;
        if (at < len(value) && value.s[at] == '-') {
            neg = true;
            at++;
        }
        int digits = 0;
        int v = 0;
        while (at < len(value) && value.s[at] >= '0' && value.s[at] <= '9') {
            v = v * 10 + (value.s[at] - '0');
            at++;
            digits++;
            if (digits > 6) {
                return false;
            }
        }
        if (digits == 0) {
            return false;
        }
        out[i] = neg ? -v : v;
    }
    return at == len(value) && out[2] > 0 && out[3] > 0;
}

bool WindowGeomRequested(int* x, int* y, int* w, int* h) {
    if (!gGeomAsked) {
        return false;
    }
    *x = gGeom[0];
    *y = gGeom[1];
    *w = gGeom[2];
    *h = gGeom[3];
    return true;
}

static bool gInspectorAsked = false;

int GpuiTakeRuntimeArgs(int argc, char** argv) {
    Str geomPrefix = StrL("-gpui-window=");
    int keep = 0;
    for (int i = 0; i < argc; i++) {
        Str argument = Str(argv[i]);
        if (i > 0 && argument && WindowTakePaintArg(argument)) {
            continue;
        }
        if (i > 0 && argument && SceneTakeArg(argument)) {
            continue;
        }
        if (i > 0 && argument && LayoutReuseTakeArg(argument)) {
            continue;
        }
        if (i > 0 && StrEq(argument, StrL("-gpui-inspector"))) {
            gInspectorAsked = true;
            continue;
        }
        if (i > 0 && StrStartsWith(argument, geomPrefix)) {
            int g[4];
            if (ParseGeom(Str(argument.s + len(geomPrefix),
                              len(argument) - len(geomPrefix)),
                          g)) {
                gGeomAsked = true;
                for (int k = 0; k < 4; k++) {
                    gGeom[k] = g[k];
                }
            }
            continue;
        }
        argv[keep++] = argv[i];
    }
    for (int i = keep; i <= argc; i++) {
        argv[i] = nullptr;
    }
    return keep;
}

