    value->open = open;
    if (value->onOpenChange.IsValid()) {
        DialogOpenChangeEvent event = {open, reason};
        ListenerCall(cx->app, cx->win, value->onOpenChange, &event);
    }
    NotifyEntity(cx->app, value->self, cx->win);
