        PanelStateNode& sn = out->nodes[ix];
        sn.kind = PanelInfoKind::Stack;
        sn.axis = n.axis;
        for (int i = 0; i < len(children); i++) {
            VecAppend(sn.children, children[i]);
            VecAppend(sn.sizes, sizes[i]);
        }
        VecReset(children);
        VecReset(sizes);
