bool LineWrapperIsWordChar(uint32_t c) {

    if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
        (c >= '0' && c <= '9')) {
        return true;
    }

    if ((c >= 0x00C0 && c <= 0x00FF) || (c >= 0x0100 && c <= 0x017F) ||
        (c >= 0x0180 && c <= 0x024F) || (c >= 0x0400 && c <= 0x04FF) ||
        (c >= 0x1E00 && c <= 0x1EFF) || (c >= 0x0300 && c <= 0x036F) ||
        (c >= 0x0980 && c <= 0x09FF)) {
        return true;
    }
    switch (c) {

        case '-':
        case '_':
        case '.':
        case '\'':
        case 0x2019:
        case 0x2018:
        case '$':
        case '%':
        case '@':
        case '#':
        case '^':
        case '~':
        case ',':
        case '=':
        case ':':
        case ';':

        case '!':
        case ')':
        case ']':
        case '}':
        case '"':
        case 0x201D:
        case 0x00BB:
        case 0x2026:

        case 0x22EF:

        case 0x202F:
        case 0x00A0:
        case 0x2011:
            return true;
        default:
            return false;
    }
}

void LineWrapperWrapLine(const LineFragment* fragments, int n, float wrapWidth,
                         WrapCharWidth widthFor, void* user,
                         Vec<WrapBoundary>* out) {
    float width = 0;
    int firstNonWhitespace = -1;
    int indent = -1;
    int lastCandidateIx = 0;
    float lastCandidateWidth = 0;
    int lastWrapIx = 0;
    uint32_t prevC = 0;
    int index = 0;
    for (int f = 0; f < n; f++) {
        const LineFragment& frag = fragments[f];
        bool element = frag.elementLen > 0 && !frag.text.s;
        int at = 0;
        while (element ? at == 0 : at < len(frag.text)) {
            int ix = index;
            uint32_t c = 0;
            int bytes = 0;
            if (element) {
                bytes = frag.elementLen;
            } else {
                bytes = Utf8At(frag.text, at, &c);
                if (bytes <= 0) {
                    bytes = 1;
                }
            }
            at += element ? 1 : bytes;
            index += bytes;
            uint32_t newPrevC = prevC;
            float itemWidth = 0;
            if (element) {
                if (prevC == ' ' && firstNonWhitespace >= 0) {
                    lastCandidateIx = ix;
                    lastCandidateWidth = width;
                }
                if (firstNonWhitespace < 0) {
                    firstNonWhitespace = ix;
                }
                itemWidth = frag.elementWidth;
            } else {
                if (c == '\n') {
                    continue;
                }
                if (LineWrapperIsWordChar(c)) {
                    if (prevC == ' ' && c != ' ' && firstNonWhitespace >= 0) {
                        lastCandidateIx = ix;
                        lastCandidateWidth = width;
                    }
                } else if (c != ' ' && firstNonWhitespace >= 0) {

                    lastCandidateIx = ix;
                    lastCandidateWidth = width;
                }
                if (c != ' ' && firstNonWhitespace < 0) {
                    firstNonWhitespace = ix;
                }
                newPrevC = c;
                itemWidth = widthFor(user, c);
            }
            width += itemWidth;
            if (width > wrapWidth && ix > lastWrapIx) {
                if (indent < 0 && firstNonWhitespace >= 0) {
                    indent = std::min(kLineWrapperMaxIndent,
                                      firstNonWhitespace - lastWrapIx);
                }
                if (lastCandidateIx > 0) {
                    lastWrapIx = lastCandidateIx;
                    width -= lastCandidateWidth;
                    lastCandidateIx = 0;
                } else {
                    lastWrapIx = ix;
                    width = itemWidth;
                }
                if (indent >= 0) {
                    width += widthFor(user, ' ') * (float)indent;
                }
                VecAppend(*out,
                          WrapBoundary{lastWrapIx, indent >= 0 ? indent : 0});
            }
            prevC = newPrevC;
        }
    }
}

enum class LbClass : uint8_t {
    Alphabetic,
    Numeric,
    Space,
    Ideographic,
    OpenPunct,
    ClosePunct,
    CloseParen,
    Exclamation,
    InfixSep,
    Solidus,
    Quotation,
    Hyphen,
    BreakAfter,
    NonStarter,
    Glue,
    WordJoiner,
    Inseparable,
    ZeroWidth,
    Combining,
};

static LbClass LbClassOf(uint32_t c) {
    if (c < 0x80) {
        if (c >= '0' && c <= '9') {
            return LbClass::Numeric;
        }
        switch (c) {
            case ' ':
                return LbClass::Space;
            case '\t':
                return LbClass::BreakAfter;
            case '(':
            case '[':
            case '{':
                return LbClass::OpenPunct;
            case ')':
            case ']':
                return LbClass::CloseParen;
            case '}':
                return LbClass::ClosePunct;
            case '!':
            case '?':
                return LbClass::Exclamation;
            case ',':
            case '.':
            case ':':
            case ';':
                return LbClass::InfixSep;
            case '/':
                return LbClass::Solidus;
            case '"':
            case '\'':
                return LbClass::Quotation;
            case '-':
                return LbClass::Hyphen;
            default:
                return LbClass::Alphabetic;
        }
    }

    if ((c >= 0x0300 && c <= 0x036F) || (c >= 0x0483 && c <= 0x0489) ||
        (c >= 0x0591 && c <= 0x05BD) || (c >= 0x0610 && c <= 0x061A) ||
        (c >= 0x064B && c <= 0x065F) || (c >= 0x1AB0 && c <= 0x1AFF) ||
        (c >= 0x1DC0 && c <= 0x1DFF) || c == 0x200C || c == 0x200D ||
        (c >= 0x20D0 && c <= 0x20FF) || (c >= 0x302A && c <= 0x302F) ||
        (c >= 0x3099 && c <= 0x309A) || (c >= 0xFE00 && c <= 0xFE0F) ||
        (c >= 0xFE20 && c <= 0xFE2F) || (c >= 0x1F3FB && c <= 0x1F3FF) ||
        (c >= 0xE0020 && c <= 0xE007F) || (c >= 0xE0100 && c <= 0xE01EF)) {
        return LbClass::Combining;
    }
    switch (c) {
        case 0x00A0:
        case 0x2007:
        case 0x2011:
        case 0x202F:
            return LbClass::Glue;
        case 0x2060:
        case 0xFEFF:
            return LbClass::WordJoiner;
        case 0x200B:
            return LbClass::ZeroWidth;
        case 0x00AD:
        case 0x2010:
        case 0x2012:
        case 0x2013:
        case 0x2027:
            return LbClass::BreakAfter;
        case 0x00AB:
        case 0x00BB:
        case 0x2018:
        case 0x2019:
        case 0x201C:
        case 0x201D:
            return LbClass::Quotation;
        case 0x2024:
        case 0x2025:
        case 0x2026:
            return LbClass::Inseparable;
        case 0x3008:
        case 0x300A:
        case 0x300C:
        case 0x300E:
        case 0x3010:
        case 0x3014:
        case 0x3016:
        case 0xFF08:
        case 0xFF3B:
        case 0xFF5B:
        case 0xFF62:
            return LbClass::OpenPunct;
        case 0x3001:
        case 0x3002:
        case 0x3009:
        case 0x300B:
        case 0x300D:
        case 0x300F:
        case 0x3011:
        case 0x3015:
        case 0x3017:
        case 0xFF09:
        case 0xFF0C:
        case 0xFF0E:
        case 0xFF3D:
        case 0xFF5D:
        case 0xFF61:
        case 0xFF63:
        case 0xFF64:
            return LbClass::ClosePunct;
        case 0xFF01:
        case 0xFF1F:
            return LbClass::Exclamation;
        case 0x3005:
        case 0x301C:
        case 0x303B:
        case 0x309D:
        case 0x309E:
        case 0x30A0:
        case 0x30FB:
        case 0x30FC:
        case 0x30FD:
        case 0x30FE:
        case 0xFF1A:
        case 0xFF1B:
        case 0xFF65:
        case 0xFF70:
            return LbClass::NonStarter;
        default:
            break;
    }

    if ((c >= 0x3041 && c <= 0x3049 && (c & 1)) || c == 0x3063 || c == 0x3083 ||
        c == 0x3085 || c == 0x3087 || c == 0x308E || c == 0x3095 ||
        c == 0x3096 || (c >= 0x30A1 && c <= 0x30AA && (c & 1)) || c == 0x30C3 ||
        c == 0x30E3 || c == 0x30E5 || c == 0x30E7 || c == 0x30EE ||
        c == 0x30F5 || c == 0x30F6) {
        return LbClass::NonStarter;
    }

    if ((c >= 0x2E80 && c <= 0xA4CF) || (c >= 0xAC00 && c <= 0xD7A3) ||
        (c >= 0xF900 && c <= 0xFAFF) || (c >= 0xFE30 && c <= 0xFE4F) ||
        (c >= 0xFF00 && c <= 0xFFEF) || (c >= 0x1F000 && c <= 0x1FAFF) ||
        (c >= 0x20000 && c <= 0x3FFFD) || (c >= 0x2600 && c <= 0x27BF)) {
        return LbClass::Ideographic;
    }
    return LbClass::Alphabetic;
}

static bool LbBreakAllowed(LbClass before, LbClass after, bool spaces) {

    if (after == LbClass::ClosePunct || after == LbClass::CloseParen ||
        after == LbClass::Exclamation || after == LbClass::InfixSep ||
        after == LbClass::Solidus) {
        return false;
    }

    if (before == LbClass::OpenPunct) {
        return false;
    }

    if ((before == LbClass::ClosePunct || before == LbClass::CloseParen) &&
        after == LbClass::NonStarter) {
        return false;
    }

    if (before == LbClass::ZeroWidth || spaces) {
        return true;
    }

    if (before == LbClass::WordJoiner || after == LbClass::WordJoiner ||
        before == LbClass::Glue) {
        return false;
    }
    if (after == LbClass::Glue) {
        return before == LbClass::BreakAfter || before == LbClass::Hyphen;
    }

    if (before == LbClass::Quotation || after == LbClass::Quotation) {
        return false;
    }

    if (after == LbClass::BreakAfter || after == LbClass::Hyphen ||
        after == LbClass::NonStarter || after == LbClass::Inseparable) {
        return false;
    }
    bool wordBefore =
        before == LbClass::Alphabetic || before == LbClass::Numeric;
    bool wordAfter = after == LbClass::Alphabetic || after == LbClass::Numeric;

    if (wordBefore && wordAfter) {
        return false;
    }

    if (after == LbClass::Numeric &&
        (before == LbClass::InfixSep || before == LbClass::Solidus ||
         before == LbClass::Hyphen)) {
        return false;
    }

    if (before == LbClass::InfixSep && after == LbClass::Alphabetic) {
        return false;
    }

    if ((wordBefore && after == LbClass::OpenPunct) ||
        (before == LbClass::CloseParen && wordAfter)) {
        return false;
    }

    return true;
}

void LineBreakOpportunities(Str text, Vec<int>* out) {
    int n = len(text);
    if (n <= 0) {
        return;
    }
    bool have = false;
    LbClass before = LbClass::Alphabetic;
    bool spaces = false;
    bool afterZwj = false;
    for (int at = 0; at < n;) {
        uint32_t c = 0;
        int bytes = Utf8At(text, at, &c);
        if (bytes <= 0) {
            bytes = 1;
        }
        LbClass cls = LbClassOf(c);
        if (cls == LbClass::Combining && have && !spaces) {

            afterZwj = c == 0x200D;
            at += bytes;
            continue;
        }
        if (cls == LbClass::Combining) {

            cls = LbClass::Alphabetic;
        }
        if (cls == LbClass::Space) {

            spaces = true;
            afterZwj = false;
            at += bytes;
            continue;
        }

        if ((have || spaces) && !afterZwj &&
            LbBreakAllowed(before, cls, spaces)) {
            VecAppend(*out, at);
        }
        before = cls;
        have = true;
        spaces = false;
        afterZwj = false;
        at += bytes;
    }

    VecAppend(*out, n);
}

void MeasuredWrapBoundaries(Str text, float width, WrappingIndent indentMode,
                            WrapMeasureFn measure, void* user,
                            Vec<WrapBoundary>* out, WrapCharWidth hint,
                            void* hintUser) {
    int n = len(text);
    if (n <= 0) {
        return;
    }
    int indent = 0;
    if (indentMode == WrappingIndent::Same) {
        while (indent < n && text.s[indent] == ' ' &&
               indent < kLineWrapperMaxIndent) {
            indent++;
        }
    }
    float indentWidth = measure(user, Str(text.s, indent));

    Vec<int> ends;
    for (int at = 0; at < n;) {
        uint32_t c = 0;
        int bytes = Utf8At(text, at, &c);
        at += bytes > 0 ? bytes : 1;
        if (TextIsGraphemeBoundary(text, at)) {
            VecAppend(ends, at);
        }
    }
    if (len(ends) == 0 || ends[len(ends) - 1] != n) {
        VecAppend(ends, n);
    }

    Vec<int> all;
    LineBreakOpportunities(text, &all);
    Vec<int> opportunities;
    for (int i = 0; i < len(all); i++) {
        if (TextIsGraphemeBoundary(text, all[i])) {
            VecAppend(opportunities, all[i]);
        }
    }
    auto widthOf = [&](int start, int end) {
        return measure(user, Str(text.s + start, end - start));
    };
    int first = 0;
    int start = 0;
    while (first < len(ends)) {
        float available = start == 0 ? width : width - indentWidth;

        int remaining = len(ends) - first;
        auto fits = [&](int count) {
            return widthOf(start, ends[first + count - 1]) <= available;
        };

        int guess = 1;
        if (hint) {
            float sum = 0;
            int from = start;
            int count = 0;
            while (count < remaining) {
                uint32_t c = 0;
                Utf8At(text, from, &c);
                sum += hint(hintUser, c);
                if (sum > available && count > 0) {
                    break;
                }
                from = ends[first + count];
                count++;
            }
            guess = std::max(count, 1);
        }

        int low = 0;
        int high = remaining + 1;
        if (fits(guess)) {
            low = guess;
            int step = 1;
            while (low < remaining) {
                int probe = std::min(low + step, remaining);
                if (!fits(probe)) {
                    high = probe;
                    break;
                }
                low = probe;
                step *= 2;
            }
        } else {
            high = guess;
            int step = 1;
            while (high - step > 0) {
                int probe = high - step;
                if (fits(probe)) {
                    low = probe;
                    break;
                }
                high = probe;
                step *= 2;
            }
        }
        while (low + 1 < high) {
            int mid = (low + high) / 2;
            if (fits(mid)) {
                low = mid;
            } else {
                high = mid;
            }
        }

        int fittingEnd = ends[first + std::max(low, 1) - 1];
        if (fittingEnd == n) {
            break;
        }

        int end = fittingEnd;
        for (int i = len(opportunities) - 1; i >= 0; i--) {
            if (opportunities[i] <= fittingEnd) {
                int ix = opportunities[i];
                if (ix > start && (start != 0 || ix > indent)) {
                    end = ix;
                }
                break;
            }
        }
        VecAppend(*out, WrapBoundary{end, indent});
        while (first < len(ends) && ends[first] <= end) {
            first++;
        }
        start = end;
    }
}

void TextWrapperWrapItem(Str line, bool wrap, WrappingIndent indent,
                         WrapLineFn wrapLine, void* user, Vec<int>* rows,
                         int* indentChars) {
    VecClear(*rows);
    int prev = 0;
    int indentOut = 0;
    if (wrap) {
        Vec<WrapBoundary> boundaries;
        wrapLine(user, line, 0, &boundaries);
        if (indent == WrappingIndent::Same) {

            for (int i = 0; i < len(boundaries); i++) {
                VecAppend(*rows, prev);
                prev = boundaries[i].ix;
                indentOut = boundaries[i].nextIndent;
            }
        } else if (len(boundaries) > 0) {

            int first = boundaries[0].ix;
            VecAppend(*rows, prev);
            prev = first;
            Vec<WrapBoundary> rest;
            wrapLine(user, Str(line.s + first, len(line) - first), first,
                     &rest);
            for (int i = 0; i < len(rest); i++) {
                VecAppend(*rows, prev);
                prev = first + rest[i].ix;
            }
        }
    }

    if (prev < len(line) || prev == 0) {
        VecAppend(*rows, prev);
    }
    if (indentChars) {
        *indentChars = indentOut;
    }
}

