static void MinMax(const float* v, int n, float* outMin, float* outMax) {
    if (n <= 0) {
        *outMin = 0;
        *outMax = 0;
        return;
    }
    float lo = v[0];
    float hi = v[0];
    for (int i = 1; i < n; i++) {
        if (v[i] < lo) {
            lo = v[i];
        }
        if (v[i] > hi) {
            hi = v[i];
        }
    }
    *outMin = lo;
    *outMax = hi;
}

static void RangeEnds(const float* range, int rangeN, float* r0, float* r1) {
    if (!range || rangeN < 2) {
        *r0 = 0;
        *r1 = 0;
        return;
    }
    *r0 = range[0];
    *r1 = range[1];
}

