TempStr AvatarInitialsTemp(Str name) {
    TempStr out = AllocStrTemp(2);

    int n = 0;
    bool atWord = true;
    for (int i = 0; i < len(name) && n < 2; i++) {
        char c = name.s[i];
        if (c == ' ') {
            atWord = true;
            continue;
        }
        if (atWord) {
            out.s[n++] = c;
            atWord = false;
        }
    }

    if (n == 1) {
        n = 0;
        for (int i = 0; i < len(name) && n < 2; i++) {
            out.s[n++] = name.s[i];
        }
    }
    for (int i = 0; i < n; i++) {
        if (out.s[i] >= 'a' && out.s[i] <= 'z') {
            out.s[i] = (char)(out.s[i] - 'a' + 'A');
        }
    }
    out.s[n] = 0;
    out.len = n;
    return out;
}

Avatar* Avatar::Name(Str s) {
    initials = StrDup(a, AvatarInitialsTemp(s));
    return this;
}

