El* CarouselControl::IntoEl() {
    CarouselState* snapshot = state.Get(cx);
    bool vertical = snapshot && snapshot->axis == Axis::Vertical;
    bool disabled =
        !snapshot || (next ? !snapshot->HasNext() : !snapshot->HasPrevious());
    IconName icon =
        vertical ? (next ? IconName::ChevronDown : IconName::ChevronUp)
                 : (next ? IconName::ChevronRight : IconName::ChevronLeft);
    Str label = accessibilityLabel.s
                    ? accessibilityLabel
                    : (next ? Tr("Carousel.next") : Tr("Carousel.previous"));
    Button* button = Button::New(cx, next ? StrL("carousel-next")
                                          : StrL("carousel-previous"))
                         ->Outline()
                         ->WithSize(size)
                         ->Rounded(1000.f)
                         ->Disabled(disabled)
                         ->AccessibilityLabel(label)
                         ->Tooltip(label);
    if (len(children) == 0)
        button->Icon(icon);
    else
        for (El* child : children) button->Child(child);
    if (!disabled)
        button->OnClick(next ? ListenTo(state, &CarouselState::OnNext)
                             : ListenTo(state, &CarouselState::OnPrevious));

    El* btn = button->IntoEl()->Absolute();
    if (!vertical) {
        btn->Top(0)->Bottom(0);
        btn->style.marginAuto |= kMarginAutoT | kMarginAutoB;
        if (next) {
            btn->LeftRel(1.f)->MarginL(Rems(cx, 1.f));
        } else {
            btn->RightRel(1.f)->MarginR(Rems(cx, 1.f));
        }
    } else {
        btn->Left(0)->Right(0);
        btn->style.marginAuto |= kMarginAutoL | kMarginAutoR;
        if (next) {
            btn->TopRel(1.f)->MarginT(Rems(cx, 1.f));
        } else {
            btn->BottomRel(1.f)->MarginB(Rems(cx, 1.f));
        }
    }
    btn->Refine(style, styleSet);
    refiner.Apply(btn);

    El* root = Div(a)->Absolute()->Top(0)->Left(0);
    if (snapshot && snapshot->frame.w > 0 && snapshot->frame.h > 0) {
        root->W(snapshot->frame.w)->H(snapshot->frame.h);
    } else {
        root->Right(0)->Bottom(0);
    }
    return root->Child(btn);
}
