El* Dialog::Header() {
    const Theme& th = ThemeNow(cx->app);
    El* head = Div(a)->FlexCol()->W(kFill)->Pad(16)->Gap(Rems(cx, 0.5f));
    El* ic = nullptr;
    if (icon != IconName::None) {
        ic = IconEl(a, icon, iconSize)->Shrink0();
        if (hasIconColor) {
            ic->Fg(iconColor);
        }
    }
    if (headerCentered) {
        head->ItemsCenter();
        if (ic) {
            head->Child(ic);
        }
        ic = nullptr;
    }
    if (title.s && len(title) > 0) {
        El* text = TextEl(a, title)->Font(16)->Semibold()->Fg(th.foreground);
        El* line = text;
        if (ic) {
            line = Div(a)
                       ->FlexRow()
                       ->Gap(Rems(cx, 0.5f))
                       ->ItemsCenter()
                       ->Child(ic)
                       ->Child(text);
        }
        head->Child(DialogTitle::New(cx)->Child(line)->IntoEl());
    } else if (ic) {
        head->Child(ic);
    }
    if (description.s && len(description) > 0) {
        head->Child(DialogDescription::New(cx)
                        ->Child(TextEl(a, description)
                                    ->Font(14)
                                    ->Fg(th.mutedFg)
                                    ->Wrap()
                                    ->W(kFill))
                        ->IntoEl());
    }
    if (body) {
        head->Child(body);
    }
    return head;
}

Str Dialog::LayerId(Str base) const {
    return StrDup(a, fmt("%s-%d", base, layerIx));
}

El* Dialog::Actions() {
    const Theme& th = ThemeNow(cx->app);
    El* row = Div(a)->W(kFill)->Pad(16)->Gap(Rems(cx, 0.5f));
    if (footerVertical) {
        row->FlexCol();
    } else {
        row->FlexRow()->JustifyEnd();
    }
    if (footerMuted) {
        row->Bg(th.tokens.muted);
    }
    if (footerDivider) {
        row->BorderT(1, th.border);
    }
    if (footer) {
        row->Child(footer);
        return row;
    }

    El* cancel = nullptr;
    if (buttonProps.IsCancelShown()) {
        cancel = buttonProps.RenderCancel(cx, LayerId(StrL("dialog-cancel")));
    }
    El* ok = buttonProps.RenderOk(cx, LayerId(StrL("dialog-ok")), okOutline);

    if (footerVertical) {
        row->Child(ok->W(kFill));
        if (cancel) {
            row->Child(cancel->W(kFill));
        }
        return row;
    }
    if (cancel) {
        row->Child(footerStretch ? cancel->Flex1() : cancel);
    }
    row->Child(footerStretch ? ok->Flex1() : ok);
    return row;
}

El* Dialog::IntoEl(WinSize size) {
    if (!open) {
        return Div(a);
    }
    const Theme& th = ThemeNow(cx->app);
    Edges windowPadding = WindowPaddings(cx->win);
    float viewW = size.dipW - windowPadding.left - windowPadding.right;
    float viewH = size.dipH - windowPadding.top - windowPadding.bottom;

    const float viewportMargin = 16.f;
    float layerOffset = (float)layerIx * 16.f;
    float y = viewH * 0.1f + layerOffset;
    float panelW = std::min(width, std::max(0.f, viewW - viewportMargin * 2));
    float panelX = (viewW - panelW) * 0.5f;
    float panelMaxH = std::max(0.f, viewH - viewportMargin * 2 - layerOffset);

    El* panel = Div(a)
                    ->W(panelW)
                    ->MaxH(panelMaxH)
                    ->FlexCol()
                    ->MinH(Rems(cx, 6))
                    ->Bg(hasBackground ? background : th.background)
                    ->Border(1, th.border)
                    ->Radius(radius > 0 ? radius : th.radiusLg)
                    ->ClipY();
    if (height > 0) {
        panel->H(height);
    }
    if (hasForeground) {
        panel->Fg(foreground);
    }
    if (surface) {
        panel->Child(surface);
    } else {
        panel->Child(Header());
        panel->Child(Actions());
    }
    if (closeButton) {

        El* x = DialogClose::New(cx)
                    ->Trigger(Button::New(cx, LayerId(StrL("dialog-close-x")))
                                  ->WithSize(UiSize::Small)
                                  ->Ghost()
                                  ->Icon(IconName::Close))
                    ->IntoEl();
        x->Absolute()->Top(8)->Right(8)->W(kAuto)->H(kAuto);
        panel->Child(x);
    }

    float delta = MotionAppear(
        cx, MotionId(StrL("dialog"), StrDup(a, fmt("%d", layerIx))),
        ANIMATION_DURATION, DialogEase);
    El* backdrop = DialogBackdrop::New(cx)
                       ->Fixed()
                       ->Top(windowPadding.top)
                       ->Left(windowPadding.left)
                       ->W(viewW)
                       ->H(viewH);
    if (overlay) {
        backdrop->Bg(th.tokens.overlay);
    }
    if (overlayClosable) {
        backdrop->PathClick(LayerId(StrL("dialog-backdrop")))
            ->OnClickAction(action::Cancel());
    }

    El* placed =
        Positioner::Corner(cx, Anchor::TopLeft,
                           {windowPadding.left + panelX, windowPadding.top + y})
            ->Margin(viewportMargin)
            ->Position(
                {windowPadding.left + panelX, windowPadding.top + y * delta})
            ->Child(panel)
            ->IntoEl();
    El* popup = DialogPopup::New(cx)
                    ->Fixed()
                    ->Top(windowPadding.top)
                    ->Left(windowPadding.left)
                    ->W(viewW)
                    ->H(viewH)
                    ->Child(placed);
    Str trap = StrDup(a, fmt("dialog-%d", layerIx));

    if (keyboard) {
        DialogBindKeys(cx, popup, trap, buttonProps.onCancel, buttonProps.onOk,
                       buttonProps.onClose);
    }
    El* host = nullptr;
    if (alertHost) {
        host = gpui::AlertDialog::New(cx)
                   ->Trap(trap)
                   ->Backdrop(backdrop)
                   ->Popup(popup)
                   ->IntoEl();
    } else {
        host = gpui::Dialog::New(cx)
                   ->Trap(trap)
                   ->Backdrop(backdrop)
                   ->Popup(popup)
                   ->IntoEl();
    }

    return host->Opacity(delta);
}

