DropdownMenu* DropdownMenu::Trigger(El* e) {
    trigger = e;
    return this;
}
DropdownMenu* DropdownMenu::Menu(PopupMenu* m) {
    menu = m;
    return this;
}
DropdownMenu* DropdownMenu::AnchorRight(bool v) {
    anchorRight = v;
    return this;
}
DropdownMenu* DropdownMenu::AnchorAbove(bool v) {
    anchorAbove = v;
    return this;
}

El* DropdownMenu::IntoEl() {

    IdScope scope(cx, id);
    El* wrap = Div(a)->Id(id)->FlexCol();
    PopupMenuState* st = menu ? menu->state.Get(cx) : nullptr;
    if (st && !st->triggerFocus.IsValid()) {
        st->triggerFocus = FocusHandleNew(cx);
    }
    if (st) {

        wrap->TrackFocus(st->triggerFocus)->TabStop(false);
    }
    if (trigger) {

        if (st) {

            if (!trigger->clickId && !trigger->clickFromPath) {
                trigger->PathClick(StrL("trigger"));
            }

            trigger
                ->OnClick(ListenTo(menu->state, &PopupMenuState::OnTriggerClick,
                                   (int64_t)st->open));
        }
        wrap->Child(trigger);
    }
    if (menu && st && st->open) {

        El* el = DropdownOpen(cx, menu->IntoEl(), MotionName(cx, StrL("open")));

        if (anchorAbove) {
            el->AnchorAbove(gap);
        } else {
            el->AnchorBelow(gap);
        }
        el->Deferred();
        if (anchorRight) {
            el->Right(0);
        } else {
            el->Left(0);
        }
        wrap->Child(el);
    }
    return wrap;
}

