El* Dot::IntoEl(Ctx* cx) const {
    float offset = size * .5f - .5f;
    El* dot = Div(cx->a)
                  ->Absolute()
                  ->W(size)
                  ->H(size)
                  ->Radius(size * .5f)
                  ->Border(1, stroke)
                  ->Bg(fill)
                  ->Left(point.x - offset)
                  ->Top(point.y - offset);
    if (halo <= 0) {
        return dot;
    }
    El* ring = Div(cx->a)
                   ->Absolute()
                   ->W(halo)
                   ->H(halo)
                   ->Radius(halo * .5f)
                   ->Bg(RgbaOpacity(fill, 0.2f))
                   ->Left(point.x - halo * .5f)
                   ->Top(point.y - halo * .5f);
    return Div(cx->a)->Absolute()->Top(0)->Left(0)->Child(ring)->Child(dot);
}

