static bool ActiveItem(const QuestionnaireState* s, Str item,
                       QuestionnaireItemState* out) {
    if (!s || !s->ItemState(item, out)) {
        ReportUnknownItem(item);
        return false;
    }
    return StrEq(s->CurrentItem(), item) && !out->disabled;
}

