namespace gpui {

namespace component {

gpui::Resizable* Resizable::New(Ctx* cx, Str id, Entity<ResizableState> state,
                                Axis axis) {

    return gpui::Resizable::New(cx, id, state, axis)
        ->WithHandleAppearance(nullptr, ResizeHandleAppearance());
}

ResizeIndicator ResizeHandleIndicator(ResizeHandleState state) {
    switch (state) {
        case ResizeHandleState::Hovered:
            return {20.f, 0.35f};
        case ResizeHandleState::Pressed:
            return {28.f, 0.6f};
        case ResizeHandleState::Dragging:
            return {44.f, 0.9f};
        case ResizeHandleState::Idle:
            break;
    }
    return {0.f, 0.f};
}

El* RenderResizeHandle(void*, const ResizeHandleContext* handle, Ctx* cx) {
    Arena* a = cx->a;
    const Theme& th = ThemeNow(cx->app);
    bool horizontal = AxisIsHorizontal(handle->AxisValue());
    ResizeIndicator target = ResizeHandleIndicator(handle->State());
    Motion policy = MotionNew(th.motion.durationFastMs)
                        .Ease(th.motion.easingMove);

    float length = MotionValue(
        cx, MotionName(cx, StrL("resizable-handle-indicator-length")),
        target.length, policy);
    float opacity = MotionValue(
        cx, MotionName(cx, StrL("resizable-handle-indicator-opacity")),
        target.opacity, policy);

    El* line = Div(a)->FlexNone()->FlexRow()->Bg(th.border);
    if (horizontal) {
        line->W(1)->H(kFill)->ItemsCenter();
    } else {
        line->H(1)->W(kFill)->ItemsStart()->JustifyCenter();
    }
    if (length > 0.5f) {

        float overhang = (kResizeIndicatorThickness - 1.f) * -0.5f;
        El* pill = Div(a)
                       ->FlexNone()
                       ->Radius(th.radiusFull)
                       ->Bg(th.mutedFg)
                       ->Opacity(opacity);
        if (horizontal) {
            pill->W(kResizeIndicatorThickness)->H(length)->MarginL(overhang);
        } else {
            pill->H(kResizeIndicatorThickness)->W(length)->MarginT(overhang);
        }

        if (handle->Edge(nullptr)) {
            pill->Deferred()->ZIndex(-1);
        }
        line->Child(pill);
    }
    return line;
}

}
}

#line 1 "src/ui/root.cpp"

namespace gpui {

namespace component {

int RootDialogOverlayIndex(const bool* wantsOverlay, int n) {
    int ix = -1;
    for (int i = 0; i < n; i++) {
        if (wantsOverlay && wantsOverlay[i]) {
            ix = i;
        }
    }
    return ix;
}

Edges RootNotificationInsets(bool hasSheet, SheetPlacement placement,
                             float size) {
    Edges e = {};
    if (!hasSheet) {
        return e;
    }
    switch (placement) {
        case SheetPlacement::Top:
            e.top = size;
            break;
        case SheetPlacement::Right:
            e.right = size;
            break;
        case SheetPlacement::Bottom:
            e.bottom = size;
            break;
        case SheetPlacement::Left:
            e.left = size;
            break;
    }
    return e;
}

El* WindowStateLayers(Ctx* cx) {
    gpui::WindowLayers* wl = WindowLayersOf(cx->win);
    if (!wl) {
        return nullptr;
    }
    Arena* a = cx->a;
    El* layers = nullptr;
    auto add = [&](El* e) {
        if (!e) {
            return;
        }
        if (!layers) {
            layers = Div(a)->Absolute()->Left(0)->Top(0)->Right(0)->Bottom(0);
        }
        layers->Child(e);
    };

    if (wl->notifications.IsValid()) {
        El* list = NotificationList::New(cx, wl->notifications)->IntoEl();
        Edges in = RootNotificationInsets(wl->hasSheet, wl->sheet.placement,
                                          wl->sheet.size);
        El* layer = Div(a)
                        ->Absolute()
                        ->Left(in.left)
                        ->Top(in.top)
                        ->Right(in.right)
                        ->Bottom(in.bottom)
                        ->Child(list);
        add(layer->Deferred());
    }
    if (wl->hasSheet) {
        if (El* s = EntityRender(cx->app, cx->win, a, wl->sheet.view)) {
            add(s->Deferred());
        }
    }

    for (int i = 0; i < wl->dialogs.len; i++) {
        if (El* d = EntityRender(cx->app, cx->win, a, wl->dialogs[i].view)) {
            add(d->Deferred());
        }
    }
    return layers;
}

static void* WindowStateBuild(Window* window, App* app) {
    WindowLayers* layers = new WindowLayers();
    layers->app = app;
    layers->win = window;
    return layers;
}

static void WindowStateDrop(void* state) {
    delete (WindowLayers*)state;
}

static void WindowStatePrepare(void*, Ctx* cx) {
    WindowSetRemSize(cx->win, ThemeNow(cx->app).fontSize);
    UiSelectionFrameBegin(cx->app);
}

static void WindowStateStyle(void*, El* surface, Ctx* cx) {
    const Theme& th = ThemeNow(cx->app);
    surface->Bg(th.tokens.background)->Fg(th.foreground);
}

static El* WindowStateDecorate(void*, El* surface, const Root*, Ctx* cx) {
    return WindowBorder::New(cx)->Child(surface)->IntoEl();
}

static El* WindowStateRender(void*, Ctx* cx) {
    El* layers = WindowStateLayers(cx);

    El* touch = WindowTouchSelectionOverlay(cx);
    El* menu = NativeMenuFallbackOverlay(cx);
    if (!touch && !menu) {
        return layers;
    }
    if (!layers) {
        layers = Div(cx->a)->Absolute()->Left(0)->Top(0)->Right(0)->Bottom(0);
    }
    if (touch) {
        layers->Child(touch);
    }
    if (menu) {
        layers->Child(menu);
    }
    return layers;
}

const RootPlugin kWindowStatePlugin = {
    &WindowStateBuild, &WindowStateDrop,     &WindowStatePrepare,
    &WindowStateStyle, &WindowStateDecorate, &WindowStateRender,
};

void RootInit(App* app) {
    Root::RegisterPlugin(app, &kWindowStatePlugin);
}

}
}

