    for (int i = 0; i < center.len; i++) {
        mid->Child(center[i]);
    }
    bar->Child(mid);
    if (hasRight) {
        El* r = region();
        for (int i = 0; i < right.len; i++) {
            r->Child(right[i]);
        }
        bar->Child(r);
    }
    return bar;
