    if (SyntaxIsIdentStart(c) || c == '-' || c == ':') {

        bool tag = lx->tagName;
        lx->tagName = false;
        while (lx->at < len(lx->src) &&
               (SyntaxIsIdent(lx->src.s[lx->at]) || lx->src.s[lx->at] == '-' ||
                lx->src.s[lx->at] == ':')) {
            lx->at++;
        }
        SyntaxEmit(lx, start, tag ? SyntaxTok::Tag : SyntaxTok::Attribute);
        return true;
    }
    (void)d;
    lx->at++;
    SyntaxEmit(lx, start, SyntaxTok::Text);
    return true;
