static El* FindTabById(El* root, Str id) {
    if (!root) {
        return nullptr;
    }
    if (base::StrEq(root->id, id)) {
        return root;
    }
    for (El* child = root->first; child; child = child->next) {
        if (El* found = FindTabById(child, id)) {
            return found;
        }
    }
    return nullptr;
}

