    component::GroupBox* box = component::GroupBox::New(request->cx);
    EachMethod<GroupBoxOp>(request, [&](const GroupBoxOp& op) {
        switch (op.kind) {
            case GroupBoxOp::Title:

                box->title = op.title;
                box->titleEl = nullptr;
                box->hasTitle = true;
                break;
            case GroupBoxOp::Variant:
                box->WithVariant(op.variant);
                break;
        }
    });
