static constexpr ArgumentDescriptor component_shell_display_rating_kValueArgs[] = {{"value", SchemaNumber()}};
static constexpr ArgumentDescriptor component_shell_display_rating_kMaxArgs[] = {{"max", SchemaNumber()}};
