    if (!PositiveUsize(args[0].number, StrL("DescriptionItem.span"), &span,
                       &error))
        return build->Fail(error);
    description_list::ItemOp* op = build->New<description_list::ItemOp>();
    op->kind = description_list::ItemOp::Span;
