        case HostValueKind::Bool:
            return "a boolean";
        case HostValueKind::Number:
            return "a number";
        case HostValueKind::String:
            return "a string";
        case HostValueKind::Array:
            return "an array";
        case HostValueKind::Object:
            return "an object";
