    ShellDialogLayer* state = layer.Get(cx);
    if (!state) return 0;
    state->app = cx->app;
    state->root = ShellRootWindowStateRoot(cx->win);
    state->content = content;
    state->isScript = isScript;
    state->options = options;
    state->focus = FocusHandleNew(cx);
