static int KeyFor(const EmscriptenKeyboardEvent* e) {
    int vk = (int)e->keyCode;
    if (vk == 0) {
        vk = (int)e->which;
    }
    if (vk == 0) {
        Str code = Str(e->code);
        if (StrEq(code, StrL("BracketLeft"))) {
            return KeyLeftBracket;
        }
        if (StrEq(code, StrL("BracketRight"))) {
            return KeyRightBracket;
        }
    }
    return vk;
}

static uint32_t CharOf(const EmscriptenKeyboardEvent* e) {
    Str key = Str(e->key);
    if (!key) {
        return 0;
    }
    uint8_t c0 = (uint8_t)key.s[0];
    int need = c0 < 0x80 ? 1 : (c0 < 0xe0 ? 2 : (c0 < 0xf0 ? 3 : 4));
    if (len(key) != need) {

        return 0;
    }
    uint32_t cp = 0;
    if (need == 1) {
        cp = c0;
    } else if (need == 2) {
        cp = ((uint32_t)(c0 & 0x1f) << 6) | (uint8_t)(key.s[1] & 0x3f);
    } else if (need == 3) {
        cp = ((uint32_t)(c0 & 0x0f) << 12) |
             ((uint32_t)(key.s[1] & 0x3f) << 6) | (uint8_t)(key.s[2] & 0x3f);
    } else {
        cp = ((uint32_t)(c0 & 0x07) << 18) |
             ((uint32_t)(key.s[1] & 0x3f) << 12) |
             ((uint32_t)(key.s[2] & 0x3f) << 6) | (uint8_t)(key.s[3] & 0x3f);
    }
    return cp;
}

static bool EditingChord(int vk) {
    return vk == KeyA || vk == KeyC || vk == KeyX || vk == KeyZ || vk == KeyY;
}

static bool AltGraphText(const EmscriptenKeyboardEvent* e) {
    return e->ctrlKey && e->altKey && CharOf(e) >= 32;
}

static bool BrowserKeepsIt(const EmscriptenKeyboardEvent* e, int vk) {
    if (AltGraphText(e)) {
        return false;
    }

    if (e->shiftKey && vk == KeyC && (e->ctrlKey || e->metaKey)) {
        return true;
    }
    if (e->metaKey) {
        return !EditingChord(vk);
    }
    if (e->ctrlKey) {

        return !EditingChord(vk);
    }

    return vk >= 112 && vk <= 123;
}

static EM_BOOL OnKeyDown(int, const EmscriptenKeyboardEvent* e, void*) {
    Window* win = gWin;
    if (!win || !win->plat || !win->plat->open) {
        return EM_FALSE;
    }
    int vk = KeyFor(e);
    bool keep = BrowserKeepsIt(e, vk);
    if (keep) {
        return EM_FALSE;
    }

    bool altGraph = AltGraphText(e);
    bool ctrl = (e->ctrlKey && !altGraph) || (e->metaKey && EditingChord(vk));
    if (vk) {

        KeyDownFlags flags;
        flags.held = e->repeat != 0;
        flags.imeInProgress =
            e->keyCode == 229 || strcmp(e->key, "Process") == 0;
        WindowKeyDown(win, vk, e->shiftKey != 0, ctrl, e->altKey && !altGraph,
                      false, false, flags);
    }

    if (vk == KeyBack) {
        WindowChar(win, 8, ctrl, e->altKey != 0);
        return EM_TRUE;
    }
    if (ctrl || e->metaKey || (e->altKey && !altGraph) || vk == KeyReturn ||
        vk == KeyTab || vk == KeyEscape) {
        return EM_TRUE;
    }
    uint32_t cp = CharOf(e);
    if (cp >= 32 && cp != 127) {
        WindowChar(win, cp, false, false);
    }
    return EM_TRUE;
}

static EM_BOOL OnKeyUp(int, const EmscriptenKeyboardEvent* e, void*) {
    Window* win = gWin;
    if (!win || !win->plat || !win->plat->open) {
        return EM_FALSE;
    }
    int vk = KeyFor(e);
    if (BrowserKeepsIt(e, vk)) {
        return EM_FALSE;
    }
    bool altGraph = AltGraphText(e);
    if (vk) {
        WindowKeyUp(
            win, vk, e->shiftKey != 0,
            (e->ctrlKey && !altGraph) || (e->metaKey && EditingChord(vk)),
            e->altKey && !altGraph, false);
    }
    return EM_TRUE;
}

static Point CanvasPoint(float clientX, float clientY) {
    float left = 0, top = 0;
    GpJsCanvasOrigin(&left, &top);
    return {clientX - left, clientY - top};
}

static Modifiers ModsOf(const EmscriptenMouseEvent* e) {
    Modifiers m;
    m.control = e->ctrlKey != 0;
    m.alt = e->altKey != 0;
    m.shift = e->shiftKey != 0;
    m.platform = e->metaKey != 0;
    return m;
}

static bool ButtonOf(unsigned short b, MouseButton* out) {
    switch (b) {
        case 0:
            *out = MouseButton::Left;
            return true;
        case 1:
            *out = MouseButton::Middle;
            return true;
        case 2:
            *out = MouseButton::Right;
            return true;
        case 3:
            *out = MouseButton::NavigateBack;
            return true;
        case 4:
            *out = MouseButton::NavigateForward;
            return true;
        default:
            return false;
    }
}

static bool HeldButton(unsigned short buttons, MouseButton* out) {
    if (buttons & 1) {
        *out = MouseButton::Left;
        return true;
    }
    if (buttons & 4) {
        *out = MouseButton::Middle;
        return true;
    }
    if (buttons & 2) {
        *out = MouseButton::Right;
        return true;
    }
    return false;
}

static EM_BOOL OnMouseDown(int, const EmscriptenMouseEvent* e, void*) {
    Window* win = gWin;
    if (!win || !win->plat || !win->plat->open) {
        return EM_FALSE;
    }
    Point p = CanvasPoint((float)e->clientX, (float)e->clientY);
    float x = p.x;
    float y = p.y;
    MouseButton button = MouseButton::Left;
    if (!ButtonOf(e->button, &button)) {
        return EM_FALSE;
    }
    Modifiers mods = ModsOf(e);

    int clicks = WindowClickCount(win, x, y, button);
    if (button == MouseButton::Left) {
        int chrome = WindowChromeHit(win, x, y);
        if (chrome == ClickWinMin) {
            AppMinimize(win);
            return EM_TRUE;
        }
        if (chrome == ClickWinMax) {
            AppToggleMaximize(win);
            return EM_TRUE;
        }
        if (chrome == ClickWinClose) {
            AppClose(win);
            return EM_TRUE;
        }
        if (chrome == ClickWinCaption) {
            if (clicks == 2) {
                AppToggleMaximize(win);
            }

            return EM_TRUE;
        }
    }
    PlatformInput in = InputMouseDown(button, x, y, mods, clicks, false);
    WindowDispatchInput(win, &in);
    return EM_TRUE;
}

static EM_BOOL OnMouseUp(int, const EmscriptenMouseEvent* e, void*) {
    Window* win = gWin;
    if (!win || !win->plat || !win->plat->open) {
        return EM_FALSE;
    }
    MouseButton button = MouseButton::Left;
    if (!ButtonOf(e->button, &button)) {
        return EM_FALSE;
    }
    Point p = CanvasPoint((float)e->clientX, (float)e->clientY);
    PlatformInput in =
        InputMouseUp(button, p.x, p.y, ModsOf(e), WindowCurrentClickCount(win));
    WindowDispatchInput(win, &in);
    return EM_TRUE;
}

static EM_BOOL OnMouseMove(int, const EmscriptenMouseEvent* e, void*) {
    Window* win = gWin;
    if (!win || !win->plat || !win->plat->open) {
        return EM_FALSE;
    }
    MouseButton held = MouseButton::Left;
    bool any = HeldButton(e->buttons, &held);
    Point p = CanvasPoint((float)e->clientX, (float)e->clientY);
    PlatformInput in = InputMouseMove(p.x, p.y, any, held, ModsOf(e));
    WindowDispatchInput(win, &in);
    return EM_TRUE;
}

static EM_BOOL OnMouseLeave(int, const EmscriptenMouseEvent* e, void*) {
    Window* win = gWin;
    if (!win || !win->plat || !win->plat->open) {
        return EM_FALSE;
    }
    MouseButton held = MouseButton::Left;
    bool any = HeldButton(e->buttons, &held);
    Point p = CanvasPoint((float)e->clientX, (float)e->clientY);
    PlatformInput in = InputMouseExited(p.x, p.y, any, held, ModsOf(e));
    WindowDispatchInput(win, &in);
    return EM_TRUE;
}

static EM_BOOL OnWheel(int, const EmscriptenWheelEvent* e, void*) {
    Window* win = gWin;
    if (!win || !win->plat || !win->plat->open) {
        return EM_FALSE;
    }

    float scale = 1.f;
    if (e->deltaMode == DOM_DELTA_LINE) {
        scale = WheelNotchPixels(win->app);
    } else if (e->deltaMode == DOM_DELTA_PAGE) {
        scale = (float)win->plat->cssH;
    }
    Point p = CanvasPoint((float)e->mouse.clientX, (float)e->mouse.clientY);
    PlatformInput in = InputScrollWheel(
        p.x, p.y, -(float)e->deltaX * scale, -(float)e->deltaY * scale,
        e->deltaMode == DOM_DELTA_PIXEL, ModsOf(&e->mouse), TouchPhase::Moved);
    WindowDispatchInput(win, &in);
    return EM_TRUE;
}

