    ClipboardItem simulated;
    if (TestPlatformClipboardRead(a, &simulated)) {
        return simulated;
    }
    ClipboardItem out;
    out.text = ClipboardGetText(a, win);
    if (!gInPasteEvent) {
        return out;
    }
    int n = GpJsClipboardImageLen();
    if (n <= 0) {
        return out;
    }
    Str image = AllocStrTemp(n);
    if (!image.s) {
        return out;
    }
    GpJsClipboardImageRead(image.s, n);
    out.imageBytes = (const uint8_t*)StrDup(a, image).s;
    out.imageBytesLen = n;
    return out;
